def encrypt(message):
    chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'
    encrypted = ''

    for char in message:
        if char in chars:
            char_index = chars.find(char)
            new_char_index = (char_index + 13) % 26
            encrypted += chars[new_char_index]
        else:
            encrypted += char
    return encrypted

