class CoordinateSystem:

    def __init__(self, x, y):
        self.x = x
        self.y = y

    def magnitude(self):
        # Returns the magnitude of the coordinate 
        return (self.x**2 + self.y**2)**(1/2)

    def add(self, other):
        # Returns the added coordinates
        x = self.x + other.x
        y = self.y + other.y
        return CoordinateSystem(x, y)

