def find_all_ways(x, y):
    if x == 0 and y == 0:
        return [[(0, 0)]]

    paths = []
    if x > 0:
        paths += find_all_ways(x-1, y)
    if y > 0:
        paths += find_all_ways(x, y-1)

    for path in paths:
        path.append((x, y))
    return paths

