def evaluate_expr(expr): 
    op, x, y = expr.split() 
    if op == '+' : 
        return float(x) + float(y) 
    if op == '-' : 
        return float(x) - float(y) 
    if op == '*' :
        return float(x) * float(y) 
    if op == '/' :
        return float(x) / float(y) 
    if op == '%':
        return float(x) % float(y)

def quicksort(arr):
    if len(arr) <= 1:
        return arr

    pivot = arr[len(arr) // 2]
    left = [x for x in arr if x < pivot]
    middle = [x for x in arr if x == pivot]
    right = [x for x in arr if x > pivot]
    return quicksort(left) + middle + quicksort(right)

