def factorial(n):
    if n == 0:
        return 1
    else:
        # Use dynamic programming
        # to store the intermediate results
        memory = {}
        if n in memory:
            return memory[n]
        else:
            memory[n] = n * factorial(n - 1)
            return memory[n]

