def caesar_cipher(message, shift):
 encrypted_message = ""
 for char in message:
 charIndex = ord(char)
 encryptedIndex = charIndex + shift
 if encryptedIndex <= 255:
 encrypted_message += chr(encryptedIndex)
 else:
 encrypted_message += chr(encryptedIndex - 255)
 return encrypted_message

