def longestSubstringWithoutRepeatingCharacters(str):
    maxLength = 0
    hashMap = dict()
    start = 0

    for i in range(len(str)):
        if str[i] in hashMap:
            start = max(hashMap[str[i]], start)

        maxLength = max(maxLength, i - start + 1)
        hashMap[str[i]] = i + 1

    return maxLength

