def subsequence(seq, sub):
    if sub == "":
        return True

    sub_index = 0
    sequence_length = len(seq)
    sub_length = len(sub)

    for index in range(sequence_length):
        if sub[sub_index] == seq[index]:
            sub_index +=1
            if sub_index == sub_length:
                return True
    return False

