def caesar_encrypt(message, shift):
    encrypted_message = ""
    for c in message:
        encrypted_c = ord(c) + shift
        if encrypted_c > 126:
            encrypted_c -= 94
        encrypted_message += chr(encrypted_c)
    return encrypted_message

def max_depth(node):
  if node is None:
    return 0

  leftDepth = max_depth(node.left)
  rightDepth = max_depth(node.right)

  if leftDepth > rightDepth:
    return leftDepth + 1
  else:
    return rightDepth + 1

