def optimize_func(x,y):
    return (x + y - (2 * x * y))

def optimize(upper_bound):
    best_val = 0
    for x in range(0, upper_bound + 1):
        for y in range(0, upper_bound + 1):
            cur_val = optimize_func(x,y)
            if cur_val > best_val:
                best_val = cur_val
    return best_val

