def fib(n): 
    # F(n) = F(n-1) + F(n-2) 
    if n<0: 
        print("Incorrect input") 
    # First Fibonacci number is 0 
    elif n==0: 
        return 0
    # Second Fibonacci number is 1 
    elif n==1: 
        return 1
    else: 
        return fib(n-1)+fib(n-2)

